struct Money { long cents; std::string currency; };

template <> struct fmt::formatter<Money> : fmt::formatter<std::string_view> {
  auto format(const Money& m, format_context& ctx) const {        // parse inherited
    return fmt::formatter<std::string_view>::format(
        fmt::format("{} {:.2f}", m.currency, m.cents / 100.0), ctx);
  }
};

std::string price_cell(const Money& m) {                  // helper called by the view
  return fmt::format("<td class=money>{}</td>", m);
}

